B.Ye=new A.kq("lee_jian","\uc774\uc9c0\uc548",14,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ISTP","\uccb4\uacb0 \uad6c\uc870 \xb7 \ucd08\ub2e8\uae30 \ub300\uc751 \ub2f4\ub2f9","\uc190\uc73c\ub85c \uc9c1\uc811 \ud655\uc778\ud574\uc57c \ub0a9\ub4dd\ud558\ub294 \uc870\uc6a9\ud558\uace0 \uc7ac\ube60\ub978 \uc218\ub9ac\uad11.","\ubb38\uc81c\ub97c \ud55c\ub3d9\uc548 \uc870\uc6a9\ud788 \ubcf4\ub2e4\uac00 \uc6d0\uc778\uc774 \ubcf4\uc774\uba74 \ubc14\ub85c \uc190\uc744 \ub304\ub2e4. \ud63c\uc790 \uc9d1\uc911\ud558\ub294 \uc2dc\uac04\uc744 \uc88b\uc544\ud558\uc9c0\ub9cc \ub204\uad70\uac00 \uc815\ub9d0 \uace4\ub780\ud560 \ub54c\ub294 \uae34 \uc124\uba85\ubcf4\ub2e4 \uba3c\uc800 \uace0\uccd0 \uc900\ub2e4.","\ub77c\ub514\uc624, \uc791\uc740 \uacf5\uad6c, \ubd84\ud574 \uac00\ub2a5\ud55c \uae30\uacc4, \uace0\uc7a5 \uc6d0\uc778 \ucc3e\uae30","\ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \uc791\ub3d9 \uc6d0\ub9ac\uc640 \ud655\uc778 \uac00\ub2a5\ud55c \uc6d0\uc778\uc73c\ub85c \uc798\uac8c \ub098\ub208\ub2e4.","\uad11\uace0\ubcf4\ub2e4 \uc2e4\uc81c \uc81c\ud488\uacfc \uc791\ub3d9 \uc6d0\ub9ac\ub97c \uc2dc\ud5d8\ud558\uace0 \uacb0\ud568\uc774 \ubc29\uce58\ub418\uba74 \ud310\ub2e4.","\ub9d0\uc740 \uc9e7\uc544\ub3c4 \ud568\uaed8 \uc791\uc5c5\ud558\uace0 \uc120\uc81c\uc801\uc73c\ub85c \ub3c4\uc640\uc8fc\ub294 \ud589\ub3d9\uc73c\ub85c \uce5c\ubc00\ud568\uc744 \ubcf4\uc778\ub2e4.",B.aIa,4286037224,u.b2)
B.aHZ=s(["\uac10\uac01","\uc81c\uc791","\uacbd\uacc4"],t.s)
B.Yi=new A.kq("choi_iseo","\ucd5c\uc774\uc11c",14,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ISFP","\ucc28\ud2b8 \ub9ac\ub4ec \xb7 \uc774\uc0c1 \uc9d5\ud6c4 \ub2f4\ub2f9","\uc0c9\uacfc \uc7ac\uc9c8, \ub2f9\uc0ac\uc790\uc758 \ud3b8\uc548\ud568\uc744 \ub193\uce58\uc9c0 \uc54a\ub294 \uc12c\uc138\ud55c \uc81c\uc791\uc790.","\ub0a8\ub4e4\uc774 \uc88b\uc544\ud558\ub294 \uac83\uacfc \uc790\uc2e0\uc774 \uc88b\uc544\ud558\ub294 \uac83\uc744 \ubd84\uba85\ud788 \uad6c\ubd84\ud55c\ub2e4. \uc870\uc6a9\ud558\uc9c0\ub9cc \uac1c\uc778\uc758 \uc120\ud0dd\uacfc \uacbd\uacc4\ub97c \uac00\ubccd\uac8c \ub118\ub294 \ud589\ub3d9\uc5d0\ub294 \ub2e8\ud638\ud558\ub2e4.","\ucc9c \uc870\uac01, \uc0c9 \uc870\ud569, \uc190\ubc14\ub290\uc9c8, \uc624\ub798 \uc368\uc11c \uc190\uc5d0 \uc775\uc740 \ubb3c\uac74","\uc22b\uc790\ub85c \uc124\uba85\ud558\uae30 \uc5b4\ub824\uc6b4 \uc0ac\uc6a9\uac10\uacfc \uc0ac\ub78c\uc758 \ubd88\ud3b8\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ubc1c\uacac\ud55c\ub2e4.","\uc0ac\ub78c\uc774 \uc2e4\uc81c\ub85c \uc4f0\uae30 \ud3b8\ud55c \uc81c\ud488\uc778\uc9c0, \uc720\ud589 \ub4a4\uc5d0\ub3c4 \ucde8\ud5a5\uc774 \ub0a8\ub294\uc9c0 \uc0b4\ud540\ub2e4.","\ucde8\ud5a5\uc744 \uac15\uc694\ud558\uc9c0 \uc54a\uace0 \uc11c\ub85c\uc758 \uc120\ud0dd\uc744 \uc874\uc911\ud560 \ub54c \uac00\uc7a5 \ud3b8\ud558\uac8c \uac00\uae4c\uc6cc\uc9c4\ub2e4.",B.aHZ,4290088168,u.cK)
