B.Yg=new A.kq("park_haeun","\ubc15\ud558\uc740",14,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ENFJ","\uc815\ubcf4\ub9dd \xb7 \ud611\uc0c1 \xb7 \uad00\uacc4 \uc704\ud5d8 \ub2f4\ub2f9","\ub9d0\ud558\uc9c0 \ubabb\ud55c \uce5c\uad6c\ub97c \ubc1c\uacac\ud558\uba74 \uadf8\ub0e5 \uc9c0\ub098\uce58\uc9c0 \ubabb\ud558\ub294 \ub2e4\uc815\ud55c \uc870\uc815\uc790.","\uc9d1\ub2e8\uc758 \ubd84\uc704\uae30\uc640 \ud63c\uc790 \uc785\uc744 \ub2eb\uc740 \uce5c\uad6c\ub97c \ud568\uaed8 \uc0b4\ud540\ub2e4. \ubaa8\ub450\ub97c \ube68\ub9ac \ud654\ud574\uc2dc\ud0a4\ub824\ub2e4 \uc2e4\uc218\ud560 \ub54c\ub3c4 \uc788\uc9c0\ub9cc, \uc0c1\ub300\uc758 \uac70\uc808\uc744 \ub4e4\uc73c\uba74 \uba48\ucd94\ub294 \ubc95\uc744 \ubc30\uc6b0\uace0 \uc788\ub2e4.","\ud568\uaed8 \uba39\ub294 \uac04\uc2dd, \uc5ed\ud560 \ub098\ub204\uae30, \uce5c\uad6c\uac00 \uc790\uae30 \uc758\uacac\uc744 \ub9d0\ud558\ub294 \uc21c\uac04","\uc11c\ub85c \ub2e4\ub978 \uc785\uc7a5\uc744 \ub9d0\ud560 \uc218 \uc788\uac8c \ub9cc\ub4e4\uace0 \uac01\uc790 \uc798\ud560 \uc5ed\ud560\uc744 \ucc3e\uc544 \uc900\ub2e4.","\uc9c1\uc6d0\uacfc \uace0\uac1d\uc774 \uc2e4\uc81c\ub85c \uc624\ub798 \uba38\ubb3c \uc218 \uc788\ub294 \uc870\uc9c1\uc778\uc9c0 \uba3c\uc800 \uad00\ucc30\ud55c\ub2e4.","\uc0c1\ub300\uac00 \uc6d0\ud558\ub294 \ub3c4\uc6c0\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubb3b\uace0, \uac00\uae4c\uc6cc\uc9c8\uc218\ub85d \uc790\uae30 \ud544\uc694\ub3c4 \uc194\uc9c1\ud788 \ub9d0\ud55c\ub2e4.",B.aMk,4294934427,u.aG)
